# flake8: noqa

import collections
import re
import select
import socket
import threading

import ta_emss.utilities.xterm_lib.asncoder as asncoder
import ta_emss.utilities.xterm_lib.message_def as message_def
import ta_emss.utilities.xterm_lib.xsocket as xsocket
from ta_emss.utilities.xterm_lib.flogger import Flogger
from ta_emss.utilities.xterm_lib.defs import *

g_debug = False


class ENBClient(threading.Thread):
    def __init__(self, client, ip_addr, db, logger=None):
        super(ENBClient, self).__init__()
        self.client = client
        self.ip_addr = ip_addr
        self.db = db
        self.running = False
        self.logger = logger
        self.num_msg_rx = 0
        self.num_msg_tx = 0
        self.hb = 0
        self.errors = 0
        self.link_state = LS_INIT  # "INIT", "CONNECTED", "CLOSED"
        self.ip_addr_str = str(self.ip_addr)
        self.asn_coder = asncoder.ASNCoder(protocol="S1AP")

    def desc(self):
        return "[{}] (hb:{}, rx:{}, tx:{}, err:{}, state:{})".format(
            self.ip_addr,
            self.hb,
            self.num_msg_rx,
            self.num_msg_tx,
            self.errors,
            self.link_state,
        )

    def run(self):
        self.running = True
        self.client.settimeout(1)
        input = [self.client]
        select_timeout = 60
        while self.running:
            self.hb += 1
            if self.errors:
                self.log("Errors exist. Closing connection...")
                self.running = False
                break

            try:
                inputready, outputready, exceptready = select.select(
                    input, [], [], select_timeout
                )
                if len(inputready):
                    data = xsocket.recv(self.client)
                    if data:
                        msg_hex = data.hex().upper()
                        self.process_msg(msg_hex)
                    else:
                        self.running = False
                        break
            except socket.timeout as err:
                self.logerror("Socket timeout: {}".format(err))
            except socket.error as err:
                self.logerror("Socket error:{}".format(err))
                self.running = False
            except select.error as err:
                self.logerror("Select error: {}.".format(err))

        self.running = False
        if self.client:
            self.client.close()
            self.client = None
        self.link_state = LS_CLOSED
        self.log("S1AP Client disconnected {}...".format(self.ip_addr_str))

    def send_msg(self, msg_hex, msg_desc):
        if not self.client:
            self.logerror(
                "Cannot send message {} - no client connected.".format(msg_desc)
            )
            return 0
        try:
            self.log("<--- Sending S1AP {}".format(msg_desc))
            self.logfile("<--- DATA SENT=[%s]\n" % msg_hex)
            xsocket.send(self.client, bytes.fromhex(msg_hex))
            self.num_msg_tx += 1
        except Exception as exc:
            self.logerror("Unable to send S1AP {} ({}).".format(msg_desc, exc))
            return 0
        return 1

    def is_running(self):
        return self.running

    def stop(self):
        self.running = False

    def process_msg(self, msg_hex):
        recv_msg = "---> Received S1AP "
        self.num_msg_rx += 1
        msg = self.asn_coder.decode_asn(msg_hex)
        if g_debug: self.logfile("S1AP: Received message:\n[{}]\n{}\n".format(msg_hex, msg))

        if msg.find("ERROR: decoding failed") != -1:
            self.logwarn("ASN decoding failed.")
            self.logfile("---> DATA RECV=[%s]\n" % msg_hex)
            # self.link_state = LS_INIT

        elif msg.find("S1SetupResponse") != -1:
            self.log(recv_msg + "S1SetupResponse")
            self.link_state = LS_CONNECTED

        elif msg.find("S1SetupFailure") != -1:
            self.logerror(recv_msg + "S1SetupFailure")
            self.link_state = LS_INIT

        elif msg.find("S1SetupRequest") != -1:
            self.log(recv_msg + "S1SetupRequest")
            msg_str = message_def.S1SetupResponse(self.db.get("MME"))
            msg_hex_enc = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex_enc, "S1SetupResponse"):
                self.link_state = LS_CONNECTED

        elif msg.find("MMEConfigurationTransfer") != -1:
            self.log(recv_msg + "MMEConfigurationTransfer")
            self.link_state = LS_CONNECTED

        elif msg.find("ENBConfigurationTransfer") != -1:
            self.log(recv_msg + "ENBConfigurationTransfer")
            self.link_state = LS_CONNECTED
            try:
                target_enb_config = {}
                source_enb_config = {}
                val = message_def.get_key_value("eNB-ID macroENB-ID", msg)
                target_enb_config["ENB_ID"] = int(
                    re.search(r"\'(.+)\'", val[0]).group(1), 2
                )
                source_enb_config["ENB_ID"] = int(
                    re.search(r"\'(.+)\'", val[1]).group(1), 2
                )

                val = message_def.get_key_value("pLMNidentity", msg)
                plmn_h = re.search(r"\'(.+)\'", val[0]).group(1)
                target_enb_config["MCC"] = plmn_h[1] + plmn_h[0] + plmn_h[3]
                target_enb_config["MNC"] = plmn_h[5] + plmn_h[4]
                plmn_h = re.search(r"\'(.+)\'", val[2]).group(1)
                source_enb_config["MCC"] = plmn_h[1] + plmn_h[0] + plmn_h[3]
                source_enb_config["MNC"] = plmn_h[5] + plmn_h[4]

                val = message_def.get_key_value("tAC", msg)
                target_enb_config["TAC"] = int(
                    re.search(r"\'(.+)\'", val[0]).group(1), 16
                )
                source_enb_config["TAC"] = int(
                    re.search(r"\'(.+)\'", val[1]).group(1), 16
                )
                self.logfile(
                    "SRC(enbid={}, mcc={}, mnc={}), TGT=(enbid={}, mcc={}, mnc={})".format(
                        source_enb_config["ENB_ID"],
                        source_enb_config["MCC"],
                        source_enb_config["MNC"],
                        target_enb_config["ENB_ID"],
                        target_enb_config["MCC"],
                        target_enb_config["MNC"],
                    )
                )

                ip_addr_str = self.db.get_enb_ip_addr(
                    enb_id=target_enb_config["ENB_ID"]
                )
                self.logfile(
                    "Got ip_addr={} for enb_id={}.".format(
                        ip_addr_str, target_enb_config["ENB_ID"]
                    )
                )
                if ip_addr_str:
                    msg_str = message_def.MMEConfigurationTransfer(
                        source_enb_config, target_enb_config, ip_addr_str
                    )
                    msg_hex_enc = self.asn_coder.encode_asn(msg_str)
                    self.send_msg(msg_hex_enc, "MMEConfigurationTransfer")
            except Exception as exc:
                self.logwarn(
                    "Cannot get target/source enb id from message[{}]:\n{}".format(
                        msg, exc
                    )
                )

        else:
            self.logwarn(recv_msg + "Unknown")
            self.logfile("---> DATA RECV=[%s]\n" % msg_hex)
            # self.link_state = LS_INIT

    def loginf(self):
        return "[" + str(self.ip_addr_str) + "] "

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.db.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        return msg_out

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.db.log_screen:
            print(msg_out)

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.errors += 1

    def logwarn(self, msg):
        msg_out = "WARN: " + msg
        self.log(msg_out)


class MME(threading.Thread):
    def __init__(self, config, logdir, db):
        super(MME, self).__init__()
        self.port = 36412
        self.logdir = logdir
        self.db = db
        self.config = config
        self.running = False
        self.logger = None
        self.errors = 0
        self.hb = 0
        self.tasks = collections.deque()
        self.socket = None
        self.ip_addr = self.config["MME_IP_ADDR"]
        self.threads = []

    def open_socket(self):
        try:
            sctp_sckt = socket.getprotobyname("sctp")
            self.socket = socket.socket(xsocket.get_socket_type(self.ip_addr), socket.SOCK_STREAM, sctp_sckt)
            if g_debug: self.log("Binding SCTP socket to addr={}".format(self.ip_addr))
            self.socket.bind((self.ip_addr, self.port))
            self.socket.listen(5)
            self.log("Listening for connections on addr={}".format(self.ip_addr))
            self.socket.settimeout(1)

        except socket.error as err:
            self.logerror("Could not open socket: {}.".format(err))
            if self.socket:
                self.socket.close()
                self.socket = None

        except Exception as exc:
            self.logerror("Exception-open_socket[{}]".format(exc))

    def desc(self):
        return "MME [{}] (hb:{}, err:{}, num_clients:{})".format(
            self.ip_addr, self.hb, self.errors, len(self.threads)
        )

    def run(self):
        if self.ip_addr is None:
            self.log("Cannot start MME server: IP address not provided.")
            return

        self.running = True

        self.open_socket()

        input = [self.socket]
        select_timeout = 60
        while self.running:
            self.hb += 1
            if self.errors:
                self.log("Errors exist. Closing connection...")
                self.running = False
                break

            if self.logger:
                self.logger.flush_if_necessary()

            try:
                inputready, outputready, exceptready = select.select(
                    input, [], [], select_timeout
                )
                # self.log("*** SELECT S1AP MME Server={}.".format(len(inputready)))
                if len(inputready):
                    try:
                        conn, addr = self.socket.accept()
                        client = ENBClient(conn, addr, self.db, logger=self.logger)
                        client.start()
                        self.threads.append(client)

                        for t in self.threads:
                            if not t.is_running():
                                t.join()
                                self.threads.remove(t)

                    except socket.timeout:
                        self.logerror("Socket timeout")
                        pass
                    except socket.error as err:
                        self.logerror("Socket error:{}".format(err))
                        self.running = False

            except select.error as err:
                self.logerror("Select error: {}.".format(err))

        self.running = False
        self.log("Stopping S1AP clients...")
        for t in self.threads:
            t.stop()
        if g_debug: self.log("Joining S1AP clients...")
        for t in self.threads:
            t.join()

        if self.socket:
            self.socket.close()
            self.socket = None

        self.log("All S1AP clients stopped.")
        if self.logger:
            self.logger.destroy()
            self.logger = None

    def is_running(self):
        return self.running

    def stop(self):
        self.running = False

    def loginf(self):
        return "[MME] "

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.db.log_screen:
            print(msg_out)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.db.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        elif not self.running:
            pass
        else:
            self.logger = Flogger(self.logdir + "/LOG-S1AP-MME.log")
            self.logger.write("=" * 80)
            self.logger.write("LID=[MME --> {}]".format(self.ip_addr))
            msg_out = self.logger.write(msg_out)
            self.logger.flush_now()
        return msg_out

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.errors += 1
